134|const SAVED_ORDERS_KEY = 'boba-builder:saved-orders-token';
135|
136|function savedOrdersToken() {
137|  const stores = [];
138|  ['localStorage', 'sessionStorage'].forEach((name) => {
139|    try { if (window[name]) stores.push(window[name]); } catch (error) { /* unavailable */ }
140|  });
141|  for (const store of stores) {
142|    try {
143|      const found = store.getItem(SAVED_ORDERS_KEY);
144|      if (/^[A-Za-z0-9_-]{20,128}$/.test(found || '')) return found;
145|    } catch (error) { /* private browsing may deny storage */ }
146|  }
147|  let token = '';
148|  if (window.crypto && window.crypto.randomUUID) {
149|    token = window.crypto.randomUUID().replace(/-/g, '') + window.crypto.randomUUID().replace(/-/g, '');
150|  } else if (window.crypto && window.crypto.getRandomValues) {
151|    const bytes = new Uint8Array(32);
152|    window.crypto.getRandomValues(bytes);
153|    token = Array.from(bytes, (value) => value.toString(16).padStart(2, '0')).join('');
154|  } else {
155|    token = `${Math.random().toString(36).slice(2)}${Date.now().toString(36)}`
156|      + Math.random().toString(36).slice(2);
157|    token = token.padEnd(32, 'x').slice(0, 64);
158|  }
159|  for (const store of stores) {
160|    try { store.setItem(SAVED_ORDERS_KEY, token); return token; } catch (error) { /* try next */ }
161|  }
162|  return token;
