+.pickup-print-head { display: none; }
+.pickup-actions { margin-top: 0; }
+.pickup-progress { margin: .7rem 0 0; font-variant-numeric: tabular-nums; }
+.label-group h4 {
+  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
+  margin: 0 0 .5rem; font-size: 1rem;
+}
+.label-count { color: var(--muted); font-size: .82rem; font-weight: 400; }
+.label-card {
+  display: flex; gap: .7rem; align-items: flex-start; padding: .7rem .8rem;
+  border: 1px solid var(--line); border-radius: 10px; background: var(--bg);
+  cursor: pointer; margin-bottom: .45rem;
+}
+.label-card.handed-out { opacity: .55; }
+.label-card.handed-out .label-drink { text-decoration: line-through; }
+.pickup-check { width: 1.35rem; height: 1.35rem; margin-top: .15rem; flex: none; accent-color: var(--ok); }
+.label-body { display: grid; gap: .1rem; min-width: 0; }
+.label-top { display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
+.label-person { font-size: 1.15rem; }
+.label-seq {
+  flex: none; font-size: .75rem; font-weight: 700; color: var(--muted);
+  border: 1px solid var(--line); border-radius: 6px; padding: .05rem .4rem;
+  font-variant-numeric: tabular-nums;
+}
+.label-drink { font-weight: 600; }
+.label-cup { font-size: .8rem; }
+.label-notes { font-size: .88rem; color: var(--brand); }
+
+/* Printing turns the on-screen checklist into cut-out slips: only the card
+   carrying the labels prints, everything interactive stays on the phone, and
+   each cup gets a dashed card of its own. */
+@media print {
+  body.printing-labels header,
+  body.printing-labels nav,
+  body.printing-labels .steps,
+  body.printing-labels .footnote,
+  body.printing-labels .actions,
+  body.printing-labels .pickup-hint,
+  body.printing-labels .pickup-progress,
+  body.printing-labels .pickup-check,
+  body.printing-labels .attention-callout { display: none !important; }
+  body.printing-labels { background: #fff; color: #000; }
+  body.printing-labels main .card { display: none !important; }
+  body.printing-labels main .card.pickup-card {
+    display: block !important; border: 0; box-shadow: none; padding: 0; margin: 0;
+  }
+  /* The labels share their card with the cart review, so only their own
+     subtree prints — first the card's children, then the review's. */
+  body.printing-labels .card.pickup-card > * { display: none !important; }
+  body.printing-labels .card.pickup-card > .cart-status,
+  body.printing-labels .card.pickup-card > .pickup-labels { display: block !important; }
+  body.printing-labels .card.pickup-card > .cart-status {
+    background: none; border: 0; padding: 0; margin: 0;
+  }
+  body.printing-labels .card.pickup-card .cart-status > * { display: none !important; }
+  body.printing-labels .card.pickup-card .cart-status > .pickup-labels {
+    display: block !important;
+  }
+  body.printing-labels .pickup-labels { border: 0; padding: 0; margin: 0; }
+  body.printing-labels .pickup-print-head {
+    display: flex; justify-content: space-between; align-items: baseline;
+    gap: 1rem; margin-bottom: .8rem; font-size: 1.1rem;
+  }
+  body.printing-labels .label-group h4 { color: #000; }
+  body.printing-labels .label-card {
+    break-inside: avoid; border: 1.5px dashed #000; background: #fff;
+    cursor: default; margin-bottom: .6rem;
+  }
+  body.printing-labels .label-card.handed-out { opacity: 1; }
+  body.printing-labels .label-card.handed-out .label-drink { text-decoration: none; }
+  body.printing-labels .label-person,
+  body.printing-labels .label-drink,
+  body.printing-labels .label-notes { color: #000; }
+}
